    from mongoengine import signals

    signals.post_save.connect(self.on_document_pre_save, sender=self.document_type)

def document_type(self):
    if isinstance(self.document_type_obj, str):
        if self.document_type_obj == RECURSIVE_REFERENCE_CONSTANT:
            self.document_type_obj = self.owner_document
        else:
            self.document_type_obj = get_document(self.document_type_obj)
    return self.document_type_obj

def __get__(self, instance, owner):
    if instance is None:
        # Document class being used rather than a document object
        return self

    # Get value from document instance if available
    value = instance._data.get(self.name)
    auto_dereference = instance._fields[self.name]._auto_dereference

    # Dereference DBRefs
    if auto_dereference and isinstance(value, DBRef):
        instance._data[self.name] = self._lazy_load_ref(self.document_type, value)

    return super().__get__(instance, owner)

def validate(self, value):
    if not isinstance(value, self.document_type):
        self.error("A CachedReferenceField only accepts documents")

    if isinstance(value, Document) and value.id is None:
        self.error(
            "You can only reference documents once they have been "
            "saved to the database"
        )

def sync_all(self):
    """
    Sync all cached fields on demand.
    Caution: this operation may be slower.
    """
    update_key = "set__%s" % self.name

    for doc in self.document_type.objects:
        filter_kwargs = {}
        filter_kwargs[self.name] = doc

        update_kwargs = {}
        update_kwargs[update_key] = doc

        self.owner_document.objects(**filter_kwargs).update(**update_kwargs)

def on_document_pre_save(self, sender, document, created, **kwargs):
    if created:
        return None

    update_kwargs = {
        f"set__{self.name}__{key}": val
        for key, val in document._delta()[0].items()
        if key in self.fields
    }
    if update_kwargs:
        filter_kwargs = {}
        filter_kwargs[self.name] = document

        self.owner_document.objects(**filter_kwargs).update(**update_kwargs)

def _clear_changed_fields(self):
    """Using _get_changed_fields iterate and remove any fields that
    are marked as changed.
    """
    ReferenceField = _import_class("ReferenceField")
    GenericReferenceField = _import_class("GenericReferenceField")

    for changed in self._get_changed_fields():
        parts = changed.split(".")
        data = self
        for part in parts:
            if isinstance(data, list):
                try:
                    data = data[int(part)]
                except IndexError:
                    data = None
            elif isinstance(data, dict):
                data = data.get(part, None)
            else:
                field_name = data._reverse_db_field_map.get(part, part)
                data = getattr(data, field_name, None)

            if not isinstance(data, LazyReference) and hasattr(
                data, "_changed_fields"
            ):
                if getattr(data, "_is_document", False):
                    continue

                data._changed_fields = []
            elif isinstance(data, (list, tuple, dict)):
                if hasattr(data, "field") and isinstance(
                    data.field, (ReferenceField, GenericReferenceField)
                ):
                    continue
                BaseDocument._nestable_types_clear_changed_fields(data)

    self._changed_fields = []

def _nestable_types_clear_changed_fields(data):
    """Inspect nested data for changed fields

    :param data: data to inspect for changes
    """
    Document = _import_class("Document")

    # Loop list / dict fields as they contain documents
    # Determine the iterator to use
    if not hasattr(data, "items"):
        iterator = enumerate(data)
    else:
        iterator = data.items()

    for _index_or_key, value in iterator:
        if hasattr(value, "_get_changed_fields") and not isinstance(
            value, Document
        ):  # don't follow references
            value._clear_changed_fields()
        elif isinstance(value, (list, tuple, dict)):
            BaseDocument._nestable_types_clear_changed_fields(value)

def _nestable_types_changed_fields(changed_fields, base_key, data):
    """Inspect nested data for changed fields

    :param changed_fields: Previously collected changed fields
    :param base_key: The base key that must be used to prepend changes to this data
    :param data: data to inspect for changes
    """
    # Loop list / dict fields as they contain documents
    # Determine the iterator to use
    if not hasattr(data, "items"):
        iterator = enumerate(data)
    else:
        iterator = data.items()

    for index_or_key, value in iterator:
        item_key = f"{base_key}{index_or_key}."
        # don't check anything lower if this key is already marked
        # as changed.
        if item_key[:-1] in changed_fields:
            continue

        if hasattr(value, "_get_changed_fields"):
            changed = value._get_changed_fields()
            changed_fields += [f"{item_key}{k}" for k in changed if k]
        elif isinstance(value, (list, tuple, dict)):
            BaseDocument._nestable_types_changed_fields(
                changed_fields, item_key, value
            )

def _delta(self):
    """Returns the delta (set, unset) of the changes for a document.
    Gets any values that have been explicitly changed.
    """
    # Handles cases where not loaded from_son but has _id
    doc = self.to_mongo()

    set_fields = self._get_changed_fields()
    unset_data = {}
    if hasattr(self, "_changed_fields"):
        set_data = {}
        # Fetch each set item from its path
        for path in set_fields:
            parts = path.split(".")
            d = doc
            new_path = []
            for p in parts:
                if isinstance(d, (ObjectId, DBRef)):
                    # Don't dig in the references
                    break
                elif isinstance(d, list) and p.isdigit():
                    # An item of a list (identified by its index) is updated
                    d = d[int(p)]
                elif hasattr(d, "get"):
                    # dict-like (dict, embedded document)
                    d = d.get(p)
                new_path.append(p)
            path = ".".join(new_path)
            set_data[path] = d
    else:
        set_data = doc
        if "_id" in set_data:
            del set_data["_id"]

    # Determine if any changed items were actually unset.
    for path, value in list(set_data.items()):
        if value or isinstance(
            value, (numbers.Number, bool)
        ):  # Account for 0 and True that are truthy
            continue

        parts = path.split(".")

        if self._dynamic and len(parts) and parts[0] in self._dynamic_fields:
            del set_data[path]
            unset_data[path] = 1
            continue

        # If we've set a value that ain't the default value don't unset it.
        default = None
        if path in self._fields:
            default = self._fields[path].default
        else:  # Perform a full lookup for lists / embedded lookups
            d = self
            db_field_name = parts.pop()
            for p in parts:
                if isinstance(d, list) and p.isdigit():
                    d = d[int(p)]
                elif hasattr(d, "__getattribute__") and not isinstance(d, dict):
                    real_path = d._reverse_db_field_map.get(p, p)
                    d = getattr(d, real_path)
                else:
                    d = d.get(p)

            if hasattr(d, "_fields"):
                field_name = d._reverse_db_field_map.get(
                    db_field_name, db_field_name
                )
                if field_name in d._fields:
                    default = d._fields.get(field_name).default
                else:
                    default = None

        if default is not None:
            default = default() if callable(default) else default

        if value != default:
            continue

        del set_data[path]
        unset_data[path] = 1
    return set_data, unset_data

def _validate_choices(self, value):
    if isinstance(value, dict):
        # If the field has not been dereferenced, it is still a dict
        # of class and DBRef
        value = value.get("_cls")
    elif isinstance(value, Document):
        value = value._class_name
    super()._validate_choices(value)

def _validate_choices(self, value):
    if isinstance(value, LazyReference):
        value = value.document_type._class_name
    super()._validate_choices(value)

def __get_field_display(self, field):
    """Return the display value for a choice field"""
    value = getattr(self, field.name)
    if field.choices and isinstance(field.choices[0], (list, tuple)):
        if value is None:
            return None
        sep = getattr(field, "display_sep", " ")
        values = (
            value
            if field.__class__.__name__ in ("ListField", "SortedListField")
            else [value]
        )
        return sep.join(
            [str(dict(field.choices).get(val, val)) for val in values or []]
        )
    return value

def __init__(self, max_bytes=None, **kwargs):
    self.max_bytes = max_bytes
    super().__init__(**kwargs)

def __init__(self, *args, **kwargs):
    self.passthrough = kwargs.pop("passthrough", False)
    super().__init__(*args, **kwargs)

def __init__(self, enum, **kwargs):
    self._enum_cls = enum
    if kwargs.get("choices"):
        invalid_choices = []
        for choice in kwargs["choices"]:
            if not isinstance(choice, enum):
                invalid_choices.append(choice)
        if invalid_choices:
            raise ValueError("Invalid choices: %r" % invalid_choices)
    else:
        kwargs["choices"] = list(self._enum_cls)  # Implicit validator
    super().__init__(**kwargs)

def validate(self, value):
    """Make sure that a geo-value is of type (x, y)"""
    if not isinstance(value, (list, tuple)):
        self.error("GeoPointField can only accept tuples or lists of (x, y)")

    if not len(value) == 2:
        self.error("Value (%s) must be a two-dimensional point" % repr(value))
    elif not isinstance(value[0], (float, int)) or not isinstance(
        value[1], (float, int)
    ):
        self.error("Both values (%s) in point must be float or int" % repr(value))

def __getattr__(self, name):
    attrs = (
        "_fs",
        "grid_id",
        "key",
        "instance",
        "db_alias",
        "collection_name",
        "newfile",
        "gridout",
    )
    if name in attrs:
        return self.__getattribute__(name)
    obj = self.get()
    if hasattr(obj, name):
        return getattr(obj, name)
    raise AttributeError

def __getattribute__(self, name):
    message = super().__getattribute__(name)
    if name == "message":
        if self.field_name:
            message = "%s" % message
        if self.errors:
            message = f"{message}({self._format_errors()})"
    return message

def fetch(self, force=False):
    if not self._cached_doc or force:
        self._cached_doc = self.document_type.objects.get(pk=self.pk)
        if not self._cached_doc:
            raise DoesNotExist("Trying to dereference unknown document %s" % (self))
    return self._cached_doc

def __getattr__(self, name):
    if not object.__getattribute__(self, "passthrough"):
        raise AttributeError()
    document = self.fetch()
    try:
        return document[name]
    except KeyError:
        raise AttributeError()

def warn_empty_is_deprecated():
    msg = "'empty' property is deprecated in favour of using 'not bool(filter)'"
    warnings.warn(msg, DeprecationWarning, stacklevel=2)

def empty(self):
    warn_empty_is_deprecated()
    return False

def empty(self):
    warn_empty_is_deprecated()
    return not bool(self.children)

def empty(self):
    warn_empty_is_deprecated()
    return not bool(self.query)

def __bool__(self):
    """Avoid to open all records in an if stmt in Py3."""
    return self._has_data()

def __get__(self, instance, owner):
    if instance is None:
        return self

    # Check if a file already exists for this model
    grid_file = instance._data.get(self.name)
    if not isinstance(grid_file, self.proxy_class):
        grid_file = self.get_proxy_obj(key=self.name, instance=instance)
        instance._data[self.name] = grid_file

    if not grid_file.key:
        grid_file.key = self.name
        grid_file.instance = instance
    return grid_file

def __set__(self, instance, value):
    key = self.name
    if (
        hasattr(value, "read") and not isinstance(value, GridFSProxy)
    ) or isinstance(value, (bytes, str)):
        # using "FileField() = file/string" notation
        grid_file = instance._data.get(self.name)
        # If a file already exists, delete it
        if grid_file:
            try:
                grid_file.delete()
            except Exception:
                pass

        # Create a new proxy object as we don't already have one
        instance._data[key] = self.get_proxy_obj(key=key, instance=instance)
        instance._data[key].put(value)
    else:
        instance._data[key] = value

    instance._mark_as_changed(key)

def get_proxy_obj(self, key, instance, db_alias=None, collection_name=None):
    if db_alias is None:
        db_alias = self.db_alias
    if collection_name is None:
        collection_name = self.collection_name

    return self.proxy_class(
        key=key,
        instance=instance,
        db_alias=db_alias,
        collection_name=collection_name,
    )

def _combine(self, other, operation):
    """Combine this node with another node into a QCombination
    object.
    """
    # If the other Q() is empty, ignore it and just use `self`.
    if not bool(other):
        return self

    # Or if this Q is empty, ignore it and just use `other`.
    if not bool(self):
        return other

    return QCombination(operation, [self, other])

def create(self, **kwargs):
    """Create new object. Returns the saved object instance."""
    return self._document(**kwargs).save(force_insert=True)

def get_version():
    """Return the VERSION as a string.

    For example, if `VERSION == (0, 10, 7)`, return '0.10.7'.
    """
    return ".".join(map(str, VERSION))

def __repr__(self):
    op = " & " if self.operation is self.AND else " | "
    return "(%s)" % op.join([repr(node) for node in self.children])

def __repr__(self):
    try:
        u = self.__str__()
    except (UnicodeEncodeError, UnicodeDecodeError):
        u = "[Bad Unicode data]"
    repr_type = str if u is None else type(u)
    return repr_type(f"<{self.__class__.__name__}: {u}>")

def __str__(self):
    # TODO this could be simpler?
    if hasattr(self, "__unicode__"):
        return self.__unicode__()
    return "%s object" % self.__class__.__name__

def fs(self):
    if not self._fs:
        self._fs = gridfs.GridFS(get_db(self.db_alias), self.collection_name)
    return self._fs

def get(self, grid_id=None):
    if grid_id:
        self.grid_id = grid_id

    if self.grid_id is None:
        return None

    try:
        if self.gridout is None:
            self.gridout = self.fs.get(self.grid_id)
        return self.gridout
    except Exception:
        # File has been deleted
        return None

def put(self, file_obj, **kwargs):
    """
    Insert a image in database
    applying field properties (size, thumbnail_size)
    """
    field = self.instance._fields[self.key]
    # Handle nested fields
    if hasattr(field, "field") and isinstance(field.field, FileField):
        field = field.field

    try:
        img = Image.open(file_obj)
        img_format = img.format
    except Exception as e:
        raise ValidationError("Invalid image: %s" % e)

    # Progressive JPEG
    # TODO: fixme, at least unused, at worst bad implementation
    progressive = img.info.get("progressive") or False

    if (
        kwargs.get("progressive")
        and isinstance(kwargs.get("progressive"), bool)
        and img_format == "JPEG"
    ):
        progressive = True
    else:
        progressive = False

    if field.size and (
        img.size[0] > field.size["width"] or img.size[1] > field.size["height"]
    ):
        size = field.size

        if size["force"]:
            img = ImageOps.fit(
                img, (size["width"], size["height"]), Image.ANTIALIAS
            )
        else:
            img.thumbnail((size["width"], size["height"]), Image.ANTIALIAS)

    thumbnail = None
    if field.thumbnail_size:
        size = field.thumbnail_size

        if size["force"]:
            thumbnail = ImageOps.fit(
                img, (size["width"], size["height"]), Image.ANTIALIAS
            )
        else:
            thumbnail = img.copy()
            thumbnail.thumbnail((size["width"], size["height"]), Image.ANTIALIAS)

    if thumbnail:
        thumb_id = self._put_thumbnail(thumbnail, img_format, progressive)
    else:
        thumb_id = None

    w, h = img.size

    io = BytesIO()
    img.save(io, img_format, progressive=progressive)
    io.seek(0)

    return super().put(
        io, width=w, height=h, format=img_format, thumbnail_id=thumb_id, **kwargs
    )

def delete(self, *args, **kwargs):
    # deletes thumbnail
    out = self.get()
    if out and out.thumbnail_id:
        self.fs.delete(out.thumbnail_id)

    return super().delete()

def _put_thumbnail(self, thumbnail, format, progressive, **kwargs):
    w, h = thumbnail.size

    io = BytesIO()
    thumbnail.save(io, format, progressive=progressive)
    io.seek(0)

    return self.fs.put(io, width=w, height=h, format=format, **kwargs)

def thumbnail(self):
    """
    return a gridfs.grid_file.GridOut
    representing a thumbnail of Image
    """
    out = self.get()
    if out and out.thumbnail_id:
        return self.fs.get(out.thumbnail_id)

def put(self, file_obj, **kwargs):
    if self.grid_id:
        raise GridFSError(
            "This document already has a file. Either delete "
            "it or call replace to overwrite it"
        )
    self.grid_id = self.fs.put(file_obj, **kwargs)
    self._mark_as_changed()

def write(self, string):
    if self.grid_id:
        if not self.newfile:
            raise GridFSError(
                "This document already has a file. Either "
                "delete it or call replace to overwrite it"
            )
    else:
        self.new_file()
    self.newfile.write(string)

def writelines(self, lines):
    if not self.newfile:
        self.new_file()
        self.grid_id = self.newfile._id
    self.newfile.writelines(lines)

def replace(self, file_obj, **kwargs):
    self.delete()
    self.put(file_obj, **kwargs)

def _mark_as_changed(self):
    """Inform the instance that `self.key` has been changed"""
    if self.instance:
        self.instance._mark_as_changed(self.key)

def __repr__(self):
    """Provide a string representation of the QuerySet"""
    if self._iter:
        return ".. queryset mid-iteration .."

    self._populate_cache()
    data = self._result_cache[: REPR_OUTPUT_SIZE + 1]
    if len(data) > REPR_OUTPUT_SIZE:
        data[-1] = "...(remaining elements truncated)..."
    return repr(data)

def no_cache(self):
    """Convert to a non-caching queryset"""
    if self._result_cache is not None:
        raise OperationError("QuerySet already cached")

    return self._clone_into(QuerySetNoCache(self._document, self._collection))

def cache(self):
    """Convert to a caching queryset"""
    return self._clone_into(QuerySet(self._document, self._collection))

def __repr__(self):
    """Provides the string representation of the QuerySet"""
    if self._iter:
        return ".. queryset mid-iteration .."

    data = []
    for _ in range(REPR_OUTPUT_SIZE + 1):
        try:
            data.append(next(self))
        except StopIteration:
            break

    if len(data) > REPR_OUTPUT_SIZE:
        data[-1] = "...(remaining elements truncated)..."

    self.rewind()
    return repr(data)

def __iter__(self):
    queryset = self
    if queryset._iter:
        queryset = self.clone()
    queryset.rewind()
    return queryset

def visit_query(self, query):
    """Called by (New)Q objects."""
    return query

def __get__(self, instance, owner):
    """Descriptor for instantiating a new QuerySet object when
    Document.objects is accessed.
    """
    if instance is not None:
        # Document object being used rather than a document class
        return self

    # owner is the document that contains the QuerySetManager
    queryset_class = owner._meta.get("queryset_class", self.default)
    queryset = queryset_class(owner, owner._get_collection())
    if self.get_queryset:
        arg_count = self.get_queryset.__code__.co_argcount
        if arg_count == 1:
            queryset = self.get_queryset(queryset)
        elif arg_count == 2:
            queryset = self.get_queryset(owner, queryset)
        else:
            queryset = partial(self.get_queryset, owner, queryset)
    return queryset

def all(self):
    """Returns a copy of the current QuerySet."""
    return self.__call__()

def filter(self, *q_objs, **query):
    """An alias of :meth:`~mongoengine.queryset.QuerySet.__call__`"""
    return self.__call__(*q_objs, **query)

def to_json(self, *args, **kwargs):
    """Converts a queryset to JSON"""
    if "json_options" not in kwargs:
        warnings.warn(
            "No 'json_options' are specified! Falling back to "
            "LEGACY_JSON_OPTIONS with uuid_representation=PYTHON_LEGACY. "
            "For use with other MongoDB drivers specify the UUID "
            "representation to use. This will be changed to "
            "uuid_representation=UNSPECIFIED in a future release.",
            DeprecationWarning,
        )
        kwargs["json_options"] = LEGACY_JSON_OPTIONS
    return json_util.dumps(self.as_pymongo(), *args, **kwargs)

def document_type(self):
    if isinstance(self.document_type_obj, str):
        if self.document_type_obj == RECURSIVE_REFERENCE_CONSTANT:
            self.document_type_obj = self.owner_document
        else:
            self.document_type_obj = get_document(self.document_type_obj)
    return self.document_type_obj

def build_lazyref(self, value):
    if isinstance(value, LazyReference):
        if value.passthrough != self.passthrough:
            value = LazyReference(
                value.document_type, value.pk, passthrough=self.passthrough
            )
    elif value is not None:
        if isinstance(value, self.document_type):
            value = LazyReference(
                self.document_type, value.pk, passthrough=self.passthrough
            )
        elif isinstance(value, DBRef):
            value = LazyReference(
                self.document_type, value.id, passthrough=self.passthrough
            )
        else:
            # value is the primary key of the referenced document
            value = LazyReference(
                self.document_type, value, passthrough=self.passthrough
            )
    return value

def __get__(self, instance, owner):
    """Descriptor to allow lazy dereferencing."""
    if instance is None:
        # Document class being used rather than a document object
        return self

    value = self.build_lazyref(instance._data.get(self.name))
    if value:
        instance._data[self.name] = value

    return super().__get__(instance, owner)

def __get__(self, instance, owner):
    if instance is None:
        return self

    value = self.build_lazyref(instance._data.get(self.name))
    if value:
        instance._data[self.name] = value

    return super().__get__(instance, owner)

def __getitem__(self, key):
    key = "_reserved_" + key if key in self._special_fields else key
    try:
        return getattr(self, key)
    except AttributeError:
        raise KeyError(key)

def to_python(self, value):
    if value is None:
        return None
    return self.to_mongo(value).to_decimal()

def visit_combination(self, combination):
    operator = "$and"
    if combination.operation == combination.OR:
        operator = "$or"
    return {operator: combination.children}

def to_dict(self):
    """Returns a dictionary of all errors within a document

    Keys are field names or list indices and values are the
    validation error messages, or a nested dictionary of
    errors for an embedded document or list.
    """

    def build_dict(source):
        errors_dict = {}
        if isinstance(source, dict):
            for field_name, error in source.items():
                errors_dict[field_name] = build_dict(error)
        elif isinstance(source, ValidationError) and source.errors:
            return build_dict(source.errors)
        else:
            return str(source)

        return errors_dict

    if not self.errors:
        return {}

    return build_dict(self.errors)

def _format_errors(self):
    """Returns a string listing all errors within a document"""

    def generate_key(value, prefix=""):
        if isinstance(value, list):
            value = " ".join([generate_key(k) for k in value])
        elif isinstance(value, dict):
            value = " ".join([generate_key(v, k) for k, v in value.items()])

        results = f"{prefix}.{value}" if prefix else value
        return results

    error_dict = defaultdict(list)
    for k, v in self.to_dict().items():
        error_dict[generate_key(v)].append(k)
    return " ".join([f"{k}: {v}" for k, v in error_dict.items()])

def build_dict(source):
    errors_dict = {}
    if isinstance(source, dict):
        for field_name, error in source.items():
            errors_dict[field_name] = build_dict(error)
    elif isinstance(source, ValidationError) and source.errors:
        return build_dict(source.errors)
    else:
        return str(source)

    return errors_dict

def generate_key(value, prefix=""):
    if isinstance(value, list):
        value = " ".join([generate_key(k) for k in value])
    elif isinstance(value, dict):
        value = " ".join([generate_key(v, k) for k, v in value.items()])

    results = f"{prefix}.{value}" if prefix else value
    return results

def __call__(self, items, max_depth=1, instance=None, name=None):
    """
    Cheaply dereferences the items to a set depth.
    Also handles the conversion of complex data types.

    :param items: The iterable (dict, list, queryset) to be dereferenced.
    :param max_depth: The maximum depth to recurse to
    :param instance: The owning instance used for tracking changes by
        :class:`~mongoengine.base.ComplexBaseField`
    :param name: The name of the field, used for tracking changes by
        :class:`~mongoengine.base.ComplexBaseField`
    :param get: A boolean determining if being called by __get__
    """
    if items is None or isinstance(items, str):
        return items

    # cheapest way to convert a queryset to a list
    # list(queryset) uses a count() query to determine length
    if isinstance(items, QuerySet):
        items = [i for i in items]

    self.max_depth = max_depth
    doc_type = None

    if instance and isinstance(
        instance, (Document, EmbeddedDocument, TopLevelDocumentMetaclass)
    ):
        doc_type = instance._fields.get(name)
        while hasattr(doc_type, "field"):
            doc_type = doc_type.field

        if isinstance(doc_type, ReferenceField):
            field = doc_type
            doc_type = doc_type.document_type
            is_list = not hasattr(items, "items")

            if is_list and all(i.__class__ == doc_type for i in items):
                return items
            elif not is_list and all(
                i.__class__ == doc_type for i in items.values()
            ):
                return items
            elif not field.dbref:
                # We must turn the ObjectIds into DBRefs

                # Recursively dig into the sub items of a list/dict
                # to turn the ObjectIds into DBRefs
                def _get_items_from_list(items):
                    new_items = []
                    for v in items:
                        value = v
                        if isinstance(v, dict):
                            value = _get_items_from_dict(v)
                        elif isinstance(v, list):
                            value = _get_items_from_list(v)
                        elif not isinstance(v, (DBRef, Document)):
                            value = field.to_python(v)
                        new_items.append(value)
                    return new_items

                def _get_items_from_dict(items):
                    new_items = {}
                    for k, v in items.items():
                        value = v
                        if isinstance(v, list):
                            value = _get_items_from_list(v)
                        elif isinstance(v, dict):
                            value = _get_items_from_dict(v)
                        elif not isinstance(v, (DBRef, Document)):
                            value = field.to_python(v)
                        new_items[k] = value
                    return new_items

                if not hasattr(items, "items"):
                    items = _get_items_from_list(items)
                else:
                    items = _get_items_from_dict(items)

    self.reference_map = self._find_references(items)
    self.object_map = self._fetch_objects(doc_type=doc_type)
    return self._attach_objects(items, 0, instance, name)

def _find_references(self, items, depth=0):
    """
    Recursively finds all db references to be dereferenced

    :param items: The iterable (dict, list, queryset)
    :param depth: The current depth of recursion
    """
    reference_map = {}
    if not items or depth >= self.max_depth:
        return reference_map

    # Determine the iterator to use
    if isinstance(items, dict):
        iterator = items.values()
    else:
        iterator = items

    # Recursively find dbreferences
    depth += 1
    for item in iterator:
        if isinstance(item, (Document, EmbeddedDocument)):
            for field_name, field in item._fields.items():
                v = item._data.get(field_name, None)
                if isinstance(v, LazyReference):
                    # LazyReference inherits DBRef but should not be dereferenced here !
                    continue
                elif isinstance(v, DBRef):
                    reference_map.setdefault(field.document_type, set()).add(v.id)
                elif isinstance(v, (dict, SON)) and "_ref" in v:
                    reference_map.setdefault(get_document(v["_cls"]), set()).add(
                        v["_ref"].id
                    )
                elif isinstance(v, (dict, list, tuple)) and depth <= self.max_depth:
                    field_cls = getattr(
                        getattr(field, "field", None), "document_type", None
                    )
                    references = self._find_references(v, depth)
                    for key, refs in references.items():
                        if isinstance(
                            field_cls, (Document, TopLevelDocumentMetaclass)
                        ):
                            key = field_cls
                        reference_map.setdefault(key, set()).update(refs)
        elif isinstance(item, LazyReference):
            # LazyReference inherits DBRef but should not be dereferenced here !
            continue
        elif isinstance(item, DBRef):
            reference_map.setdefault(item.collection, set()).add(item.id)
        elif isinstance(item, (dict, SON)) and "_ref" in item:
            reference_map.setdefault(get_document(item["_cls"]), set()).add(
                item["_ref"].id
            )
        elif isinstance(item, (dict, list, tuple)) and depth - 1 <= self.max_depth:
            references = self._find_references(item, depth - 1)
            for key, refs in references.items():
                reference_map.setdefault(key, set()).update(refs)

    return reference_map

def _attach_objects(self, items, depth=0, instance=None, name=None):
    """
    Recursively finds all db references to be dereferenced

    :param items: The iterable (dict, list, queryset)
    :param depth: The current depth of recursion
    :param instance: The owning instance used for tracking changes by
        :class:`~mongoengine.base.ComplexBaseField`
    :param name: The name of the field, used for tracking changes by
        :class:`~mongoengine.base.ComplexBaseField`
    """
    if not items:
        if isinstance(items, (BaseDict, BaseList)):
            return items

        if instance:
            if isinstance(items, dict):
                return BaseDict(items, instance, name)
            else:
                return BaseList(items, instance, name)

    if isinstance(items, (dict, SON)):
        if "_ref" in items:
            return self.object_map.get(
                (items["_ref"].collection, items["_ref"].id), items
            )
        elif "_cls" in items:
            doc = get_document(items["_cls"])._from_son(items)
            _cls = doc._data.pop("_cls", None)
            del items["_cls"]
            doc._data = self._attach_objects(doc._data, depth, doc, None)
            if _cls is not None:
                doc._data["_cls"] = _cls
            return doc

    if not hasattr(items, "items"):
        is_list = True
        list_type = BaseList
        if isinstance(items, EmbeddedDocumentList):
            list_type = EmbeddedDocumentList
        as_tuple = isinstance(items, tuple)
        iterator = enumerate(items)
        data = []
    else:
        is_list = False
        iterator = items.items()
        data = {}

    depth += 1
    for k, v in iterator:
        if is_list:
            data.append(v)
        else:
            data[k] = v

        if k in self.object_map and not is_list:
            data[k] = self.object_map[k]
        elif isinstance(v, (Document, EmbeddedDocument)):
            for field_name in v._fields:
                v = data[k]._data.get(field_name, None)
                if isinstance(v, DBRef):
                    data[k]._data[field_name] = self.object_map.get(
                        (v.collection, v.id), v
                    )
                elif isinstance(v, (dict, SON)) and "_ref" in v:
                    data[k]._data[field_name] = self.object_map.get(
                        (v["_ref"].collection, v["_ref"].id), v
                    )
                elif isinstance(v, (dict, list, tuple)) and depth <= self.max_depth:
                    item_name = f"{name}.{k}.{field_name}"
                    data[k]._data[field_name] = self._attach_objects(
                        v, depth, instance=instance, name=item_name
                    )
        elif isinstance(v, (dict, list, tuple)) and depth <= self.max_depth:
            item_name = f"{name}.{k}" if name else name
            data[k] = self._attach_objects(
                v, depth - 1, instance=instance, name=item_name
            )
        elif isinstance(v, DBRef) and hasattr(v, "id"):
            data[k] = self.object_map.get((v.collection, v.id), v)

    if instance and name:
        if is_list:
            return tuple(data) if as_tuple else list_type(data, instance, name)
        return BaseDict(data, instance, name)
    depth += 1
    return data

def _get_items_from_list(items):
    new_items = []
    for v in items:
        value = v
        if isinstance(v, dict):
            value = _get_items_from_dict(v)
        elif isinstance(v, list):
            value = _get_items_from_list(v)
        elif not isinstance(v, (DBRef, Document)):
            value = field.to_python(v)
        new_items.append(value)
    return new_items

def _get_items_from_dict(items):
    new_items = {}
    for k, v in items.items():
        value = v
        if isinstance(v, list):
            value = _get_items_from_list(v)
        elif isinstance(v, dict):
            value = _get_items_from_dict(v)
        elif not isinstance(v, (DBRef, Document)):
            value = field.to_python(v)
        new_items[k] = value
    return new_items

def _fetch_objects(self, doc_type=None):
    """Fetch all references and convert to their document objects"""
    object_map = {}
    for collection, dbrefs in self.reference_map.items():
        # we use getattr instead of hasattr because hasattr swallows any exception under python2
        # so it could hide nasty things without raising exceptions (cfr bug #1688))
        ref_document_cls_exists = getattr(collection, "objects", None) is not None

        if ref_document_cls_exists:
            col_name = collection._get_collection_name()
            refs = [
                dbref for dbref in dbrefs if (col_name, dbref) not in object_map
            ]
            references = collection.objects.in_bulk(refs)
            for key, doc in references.items():
                object_map[(col_name, key)] = doc
        else:  # Generic reference: use the refs data to convert to document
            if isinstance(doc_type, (ListField, DictField, MapField)):
                continue

            refs = [
                dbref for dbref in dbrefs if (collection, dbref) not in object_map
            ]

            if doc_type:
                references = doc_type._get_db()[collection].find(
                    {"_id": {"$in": refs}}
                )
                for ref in references:
                    doc = doc_type._from_son(ref)
                    object_map[(collection, doc.id)] = doc
            else:
                references = get_db()[collection].find({"_id": {"$in": refs}})
                for ref in references:
                    if "_cls" in ref:
                        doc = get_document(ref["_cls"])._from_son(ref)
                    elif doc_type is None:
                        doc = get_document(
                            "".join(x.capitalize() for x in collection.split("_"))
                        )._from_son(ref)
                    else:
                        doc = doc_type._from_son(ref)
                    object_map[(collection, doc.id)] = doc
    return object_map

def __getitem__(self, key):
    """Return a document instance corresponding to a given index if
    the key is an integer. If the key is a slice, translate its
    bounds into a skip and a limit, and return a cloned queryset
    with that skip/limit applied. For example:

    >>> User.objects[0]
    <User: User object>
    >>> User.objects[1:3]
    [<User: User object>, <User: User object>]
    """
    queryset = self.clone()
    queryset._empty = False

    # Handle a slice
    if isinstance(key, slice):
        queryset._cursor_obj = queryset._cursor[key]
        queryset._skip, queryset._limit = key.start, key.stop
        if key.start and key.stop:
            queryset._limit = key.stop - key.start
        if queryset._limit == 0:
            queryset._empty = True

        # Allow further QuerySet modifications to be performed
        return queryset

    # Handle an index
    elif isinstance(key, int):
        if queryset._scalar:
            return queryset._get_scalar(
                queryset._document._from_son(
                    queryset._cursor[key],
                    _auto_dereference=self._auto_dereference,
                )
            )

        if queryset._as_pymongo:
            return queryset._cursor[key]

        return queryset._document._from_son(
            queryset._cursor[key],
            _auto_dereference=self._auto_dereference,
        )

    raise TypeError("Provide a slice or an integer index")

def in_bulk(self, object_ids):
    """Retrieve a set of documents by their ids.

    :param object_ids: a list or tuple of ObjectId's
    :rtype: dict of ObjectId's as keys and collection-specific
            Document subclasses as values.
    """
    doc_map = {}

    docs = self._collection.find({"_id": {"$in": object_ids}}, **self._cursor_args)
    if self._scalar:
        for doc in docs:
            doc_map[doc["_id"]] = self._get_scalar(self._document._from_son(doc))
    elif self._as_pymongo:
        for doc in docs:
            doc_map[doc["_id"]] = doc
    else:
        for doc in docs:
            doc_map[doc["_id"]] = self._document._from_son(
                doc,
                _auto_dereference=self._auto_dereference,
            )

    return doc_map

def __next__(self):
    """Wrap the result in a :class:`~mongoengine.Document` object."""
    if self._none or self._empty:
        raise StopIteration

    raw_doc = next(self._cursor)

    if self._as_pymongo:
        return raw_doc

    doc = self._document._from_son(
        raw_doc,
        _auto_dereference=self._auto_dereference,
    )

    if self._scalar:
        return self._get_scalar(doc)

    return doc

def _get_scalar(self, doc):
    def lookup(obj, name):
        chunks = name.split("__")
        for chunk in chunks:
            obj = getattr(obj, chunk)
        return obj

    data = [lookup(doc, n) for n in self._scalar]
    if len(data) == 1:
        return data[0]

    return tuple(data)

def lookup(obj, name):
    chunks = name.split("__")
    for chunk in chunks:
        obj = getattr(obj, chunk)
    return obj

def _from_son(cls, son, _auto_dereference=True, created=False):
    """Create an instance of a Document (subclass) from a PyMongo SON (dict)"""
    if son and not isinstance(son, dict):
        raise ValueError(
            "The source SON object needs to be of type 'dict' but a '%s' was found"
            % type(son)
        )

    # Get the class name from the document, falling back to the given
    # class if unavailable
    class_name = son.get("_cls", cls._class_name)

    # Convert SON to a data dict, making sure each key is a string and
    # corresponds to the right db field.
    # This is needed as _from_son is currently called both from BaseDocument.__init__
    # and from EmbeddedDocumentField.to_python
    data = {}
    for key, value in son.items():
        key = str(key)
        key = cls._db_field_map.get(key, key)
        data[key] = value

    # Return correct subclass for document type
    if class_name != cls._class_name:
        cls = get_document(class_name)

    errors_dict = {}

    fields = cls._fields
    if not _auto_dereference:
        fields = copy.deepcopy(fields)

    for field_name, field in fields.items():
        field._auto_dereference = _auto_dereference
        if field.db_field in data:
            value = data[field.db_field]
            try:
                data[field_name] = (
                    value if value is None else field.to_python(value)
                )
                if field_name != field.db_field:
                    del data[field.db_field]
            except (AttributeError, ValueError) as e:
                errors_dict[field_name] = e

    if errors_dict:
        errors = "\n".join([f"Field '{k}' - {v}" for k, v in errors_dict.items()])
        msg = "Invalid data to create a `{}` instance.\n{}".format(
            cls._class_name,
            errors,
        )
        raise InvalidDocumentError(msg)

    # In STRICT documents, remove any keys that aren't in cls._fields
    if cls.STRICT:
        data = {k: v for k, v in data.items() if k in cls._fields}

    obj = cls(__auto_convert=False, _created=created, **data)
    obj._changed_fields = []
    if not _auto_dereference:
        obj._fields = fields

    return obj

def __iter__(self):
    """Iteration utilises a results cache which iterates the cursor
    in batches of ``ITER_CHUNK_SIZE``.

    If ``self._has_more`` the cursor hasn't been exhausted so cache then
    batch. Otherwise iterate the result_cache.
    """
    self._iter = True

    if self._has_more:
        return self._iter_results()

    # iterating over the cache.
    return iter(self._result_cache)

def query(_doc_cls=None, **kwargs):
    """Transform a query from Django-style format to Mongo format."""
    mongo_query = {}
    merge_query = defaultdict(list)
    for key, value in sorted(kwargs.items()):
        if key == "__raw__":
            mongo_query.update(value)
            continue

        parts = key.rsplit("__")
        indices = [(i, p) for i, p in enumerate(parts) if p.isdigit()]
        parts = [part for part in parts if not part.isdigit()]
        # Check for an operator and transform to mongo-style if there is
        op = None
        if len(parts) > 1 and parts[-1] in MATCH_OPERATORS:
            op = parts.pop()

        # Allow to escape operator-like field name by __
        if len(parts) > 1 and parts[-1] == "":
            parts.pop()

        negate = False
        if len(parts) > 1 and parts[-1] == "not":
            parts.pop()
            negate = True

        if _doc_cls:
            # Switch field names to proper names [set in Field(name='foo')]
            try:
                fields = _doc_cls._lookup_field(parts)
            except Exception as e:
                raise InvalidQueryError(e)
            parts = []

            CachedReferenceField = _import_class("CachedReferenceField")
            GenericReferenceField = _import_class("GenericReferenceField")

            cleaned_fields = []
            for field in fields:
                append_field = True
                if isinstance(field, str):
                    parts.append(field)
                    append_field = False
                # is last and CachedReferenceField
                elif isinstance(field, CachedReferenceField) and fields[-1] == field:
                    parts.append("%s._id" % field.db_field)
                else:
                    parts.append(field.db_field)

                if append_field:
                    cleaned_fields.append(field)

            # Convert value to proper value
            field = cleaned_fields[-1]

            singular_ops = [None, "ne", "gt", "gte", "lt", "lte", "not"]
            singular_ops += STRING_OPERATORS
            if op in singular_ops:
                value = field.prepare_query_value(op, value)

                if isinstance(field, CachedReferenceField) and value:
                    value = value["_id"]

            elif op in ("in", "nin", "all", "near") and not isinstance(value, dict):
                # Raise an error if the in/nin/all/near param is not iterable.
                value = _prepare_query_for_iterable(field, op, value)

            # If we're querying a GenericReferenceField, we need to alter the
            # key depending on the value:
            # * If the value is a DBRef, the key should be "field_name._ref".
            # * If the value is an ObjectId, the key should be "field_name._ref.$id".
            if isinstance(field, GenericReferenceField):
                if isinstance(value, DBRef):
                    parts[-1] += "._ref"
                elif isinstance(value, ObjectId):
                    parts[-1] += "._ref.$id"

        # if op and op not in COMPARISON_OPERATORS:
        if op:
            if op in GEO_OPERATORS:
                value = _geo_operator(field, op, value)
            elif op in ("match", "elemMatch"):
                ListField = _import_class("ListField")
                EmbeddedDocumentField = _import_class("EmbeddedDocumentField")
                if (
                    isinstance(value, dict)
                    and isinstance(field, ListField)
                    and isinstance(field.field, EmbeddedDocumentField)
                ):
                    value = query(field.field.document_type, **value)
                else:
                    value = field.prepare_query_value(op, value)
                value = {"$elemMatch": value}
            elif op in CUSTOM_OPERATORS:
                NotImplementedError(
                    'Custom method "%s" has not ' "been implemented" % op
                )
            elif op not in STRING_OPERATORS:
                value = {"$" + op: value}

        if negate:
            value = {"$not": value}

        for i, part in indices:
            parts.insert(i, part)

        key = ".".join(parts)

        if key not in mongo_query:
            mongo_query[key] = value
        else:
            if isinstance(mongo_query[key], dict) and isinstance(value, dict):
                mongo_query[key].update(value)
                # $max/minDistance needs to come last - convert to SON
                value_dict = mongo_query[key]
                if ("$maxDistance" in value_dict or "$minDistance" in value_dict) and (
                    "$near" in value_dict or "$nearSphere" in value_dict
                ):
                    value_son = SON()
                    for k, v in value_dict.items():
                        if k == "$maxDistance" or k == "$minDistance":
                            continue
                        value_son[k] = v
                    # Required for MongoDB >= 2.6, may fail when combining
                    # PyMongo 3+ and MongoDB < 2.6
                    near_embedded = False
                    for near_op in ("$near", "$nearSphere"):
                        if isinstance(value_dict.get(near_op), dict):
                            value_son[near_op] = SON(value_son[near_op])
                            if "$maxDistance" in value_dict:
                                value_son[near_op]["$maxDistance"] = value_dict[
                                    "$maxDistance"
                                ]
                            if "$minDistance" in value_dict:
                                value_son[near_op]["$minDistance"] = value_dict[
                                    "$minDistance"
                                ]
                            near_embedded = True

                    if not near_embedded:
                        if "$maxDistance" in value_dict:
                            value_son["$maxDistance"] = value_dict["$maxDistance"]
                        if "$minDistance" in value_dict:
                            value_son["$minDistance"] = value_dict["$minDistance"]
                    mongo_query[key] = value_son
            else:
                # Store for manually merging later
                merge_query[key].append(value)

    # The queryset has been filter in such a way we must manually merge
    for k, v in merge_query.items():
        merge_query[k].append(mongo_query[k])
        del mongo_query[k]
        if isinstance(v, list):
            value = [{k: val} for val in v]
            if "$and" in mongo_query.keys():
                mongo_query["$and"].extend(value)
            else:
                mongo_query["$and"] = value

    return mongo_query

def update(_doc_cls=None, **update):
    """Transform an update spec from Django-style format to Mongo
    format.
    """
    mongo_update = {}

    for key, value in update.items():
        if key == "__raw__":
            mongo_update.update(value)
            continue

        parts = key.split("__")

        # if there is no operator, default to 'set'
        if len(parts) < 3 and parts[0] not in UPDATE_OPERATORS:
            parts.insert(0, "set")

        # Check for an operator and transform to mongo-style if there is
        op = None
        if parts[0] in UPDATE_OPERATORS:
            op = parts.pop(0)
            # Convert Pythonic names to Mongo equivalents
            operator_map = {
                "push_all": "pushAll",
                "pull_all": "pullAll",
                "dec": "inc",
                "add_to_set": "addToSet",
                "set_on_insert": "setOnInsert",
            }
            if op == "dec":
                # Support decrement by flipping a positive value's sign
                # and using 'inc'
                value = -value
            # If the operator doesn't found from operator map, the op value
            # will stay unchanged
            op = operator_map.get(op, op)

        match = None

        if len(parts) == 1:
            # typical update like set__field
            # but also allows to update a field named like a comparison operator
            # like set__type = "something" (without clashing with the 'type' operator)
            pass
        elif len(parts) > 1:
            # can be either an embedded field like set__foo__bar
            # or a comparison operator as in pull__foo__in
            if parts[-1] in COMPARISON_OPERATORS:
                match = parts.pop()  # e.g. pop 'in' from pull__foo__in

            # Allow to escape operator-like field name by __
            # e.g. in the case of an embedded foo.type field
            # Doc.objects().update(set__foo__type="bar")
            # see https://github.com/MongoEngine/mongoengine/pull/1351
            if parts[-1] == "":
                match = parts.pop()  # e.g. pop last '__' from set__foo__type__

        if _doc_cls:
            # Switch field names to proper names [set in Field(name='foo')]
            try:
                fields = _doc_cls._lookup_field(parts)
            except Exception as e:
                raise InvalidQueryError(e)
            parts = []

            cleaned_fields = []
            appended_sub_field = False
            for field in fields:
                append_field = True
                if isinstance(field, str):
                    # Convert the S operator to $
                    if field == "S":
                        field = "$"
                    parts.append(field)
                    append_field = False
                else:
                    parts.append(field.db_field)
                if append_field:
                    appended_sub_field = False
                    cleaned_fields.append(field)
                    if hasattr(field, "field"):
                        cleaned_fields.append(field.field)
                        appended_sub_field = True

            # Convert value to proper value
            if appended_sub_field:
                field = cleaned_fields[-2]
            else:
                field = cleaned_fields[-1]

            GeoJsonBaseField = _import_class("GeoJsonBaseField")
            if isinstance(field, GeoJsonBaseField):
                value = field.to_mongo(value)

            if op == "pull":
                if field.required or value is not None:
                    if match in ("in", "nin") and not isinstance(value, dict):
                        value = _prepare_query_for_iterable(field, op, value)
                    else:
                        value = field.prepare_query_value(op, value)
            elif op == "push" and isinstance(value, (list, tuple, set)):
                value = [field.prepare_query_value(op, v) for v in value]
            elif op in (None, "set", "push"):
                if field.required or value is not None:
                    value = field.prepare_query_value(op, value)
            elif op in ("pushAll", "pullAll"):
                value = [field.prepare_query_value(op, v) for v in value]
            elif op in ("addToSet", "setOnInsert"):
                if isinstance(value, (list, tuple, set)):
                    value = [field.prepare_query_value(op, v) for v in value]
                elif field.required or value is not None:
                    value = field.prepare_query_value(op, value)
            elif op == "unset":
                value = 1
            elif op == "inc":
                value = field.prepare_query_value(op, value)

        if match:
            match = "$" + match
            value = {match: value}

        key = ".".join(parts)

        if "pull" in op and "." in key:
            # Dot operators don't work on pull operations
            # unless they point to a list field
            # Otherwise it uses nested dict syntax
            if op == "pullAll":
                raise InvalidQueryError(
                    "pullAll operations only support a single field depth"
                )

            # Look for the last list field and use dot notation until there
            field_classes = [c.__class__ for c in cleaned_fields]
            field_classes.reverse()
            ListField = _import_class("ListField")
            EmbeddedDocumentListField = _import_class("EmbeddedDocumentListField")
            if ListField in field_classes or EmbeddedDocumentListField in field_classes:
                # Join all fields via dot notation to the last ListField or EmbeddedDocumentListField
                # Then process as normal
                if ListField in field_classes:
                    _check_field = ListField
                else:
                    _check_field = EmbeddedDocumentListField

                last_listField = len(cleaned_fields) - field_classes.index(_check_field)
                key = ".".join(parts[:last_listField])
                parts = parts[last_listField:]
                parts.insert(0, key)

            parts.reverse()
            for key in parts:
                value = {key: value}
        elif op == "addToSet" and isinstance(value, list):
            value = {key: {"$each": value}}
        elif op in ("push", "pushAll"):
            if parts[-1].isdigit():
                key = ".".join(parts[0:-1])
                position = int(parts[-1])
                # $position expects an iterable. If pushing a single value,
                # wrap it in a list.
                if not isinstance(value, (set, tuple, list)):
                    value = [value]
                value = {key: {"$each": value, "$position": position}}
            else:
                if op == "pushAll":
                    op = "push"  # convert to non-deprecated keyword
                    if not isinstance(value, (set, tuple, list)):
                        value = [value]
                    value = {key: {"$each": value}}
                else:
                    value = {key: value}
        else:
            value = {key: value}
        key = "$" + op
        if key not in mongo_update:
            mongo_update[key] = value
        elif key in mongo_update and isinstance(mongo_update[key], dict):
            mongo_update[key].update(value)

    return mongo_update

def _geo_operator(field, op, value):
    """Helper to return the query for a given geo query."""
    if op == "max_distance":
        value = {"$maxDistance": value}
    elif op == "min_distance":
        value = {"$minDistance": value}
    elif field._geo_index == pymongo.GEO2D:
        if op == "within_distance":
            value = {"$within": {"$center": value}}
        elif op == "within_spherical_distance":
            value = {"$within": {"$centerSphere": value}}
        elif op == "within_polygon":
            value = {"$within": {"$polygon": value}}
        elif op == "near":
            value = {"$near": value}
        elif op == "near_sphere":
            value = {"$nearSphere": value}
        elif op == "within_box":
            value = {"$within": {"$box": value}}
        else:
            raise NotImplementedError(
                'Geo method "%s" has not been ' "implemented for a GeoPointField" % op
            )
    else:
        if op == "geo_within":
            value = {"$geoWithin": _infer_geometry(value)}
        elif op == "geo_within_box":
            value = {"$geoWithin": {"$box": value}}
        elif op == "geo_within_polygon":
            value = {"$geoWithin": {"$polygon": value}}
        elif op == "geo_within_center":
            value = {"$geoWithin": {"$center": value}}
        elif op == "geo_within_sphere":
            value = {"$geoWithin": {"$centerSphere": value}}
        elif op == "geo_intersects":
            value = {"$geoIntersects": _infer_geometry(value)}
        elif op == "near":
            value = {"$near": _infer_geometry(value)}
        else:
            raise NotImplementedError(
                'Geo method "{}" has not been implemented for a {} '.format(
                    op, field._name
                )
            )
    return value

def _infer_geometry(value):
    """Helper method that tries to infer the $geometry shape for a
    given value.
    """
    if isinstance(value, dict):
        if "$geometry" in value:
            return value
        elif "coordinates" in value and "type" in value:
            return {"$geometry": value}
        raise InvalidQueryError(
            "Invalid $geometry dictionary should have type and coordinates keys"
        )
    elif isinstance(value, (list, set)):
        # TODO: shouldn't we test value[0][0][0][0] to see if it is MultiPolygon?

        try:
            value[0][0][0]
            return {"$geometry": {"type": "Polygon", "coordinates": value}}
        except (TypeError, IndexError):
            pass

        try:
            value[0][0]
            return {"$geometry": {"type": "LineString", "coordinates": value}}
        except (TypeError, IndexError):
            pass

        try:
            value[0]
            return {"$geometry": {"type": "Point", "coordinates": value}}
        except (TypeError, IndexError):
            pass

    raise InvalidQueryError(
        "Invalid $geometry data. Can be either a "
        "dictionary or (nested) lists of coordinate(s)"
    )

def visit_combination(self, combination):
    """Called by QCombination objects."""
    return combination

def __init__(self, operation, children):
    self.operation = operation
    self.children = []
    for node in children:
        # If the child is a combination of the same type, we can merge its
        # children directly into this combinations children
        if isinstance(node, QCombination) and node.operation == operation:
            self.children += node.children
        else:
            self.children.append(node)

def __init__(self, **kwargs):
    for k, v in kwargs.items():
        setattr(self, k, v)

def visit_combination(self, combination):
    if combination.operation == combination.AND:
        # The simplification only applies to 'simple' queries
        if all(isinstance(node, Q) for node in combination.children):
            queries = [n.query for n in combination.children]
            try:
                return Q(**self._query_conjunction(queries))
            except DuplicateQueryConditionsError:
                # Cannot be simplified
                pass
    return combination

def accept(self, visitor):
    for i in range(len(self.children)):
        if isinstance(self.children[i], QNode):
            self.children[i] = self.children[i].accept(visitor)

    return visitor.visit_combination(self)

def get_text_score(self):
    """
    Get text score from text query
    """

    if "_text_score" not in self._data:
        raise InvalidDocumentError(
            "This document is not originally built from a text query"
        )

    return self._data["_text_score"]

def delete(self, write_concern=None, _from_doc_delete=False, cascade_refs=None):
    """Delete the documents matched by the query.

    :param write_concern: Extra keyword arguments are passed down which
        will be used as options for the resultant
        ``getLastError`` command.  For example,
        ``save(..., write_concern={w: 2, fsync: True}, ...)`` will
        wait until at least two servers have recorded the write and
        will force an fsync on the primary server.
    :param _from_doc_delete: True when called from document delete therefore
        signals will have been triggered so don't loop.

    :returns number of deleted documents
    """
    queryset = self.clone()
    doc = queryset._document

    if write_concern is None:
        write_concern = {}

    # Handle deletes where skips or limits have been applied or
    # there is an untriggered delete signal
    has_delete_signal = signals.signals_available and (
        signals.pre_delete.has_receivers_for(doc)
        or signals.post_delete.has_receivers_for(doc)
    )

    call_document_delete = (
        queryset._skip or queryset._limit or has_delete_signal
    ) and not _from_doc_delete

    if call_document_delete:
        cnt = 0
        for doc in queryset:
            doc.delete(**write_concern)
            cnt += 1
        return cnt

    delete_rules = doc._meta.get("delete_rules") or {}
    delete_rules = list(delete_rules.items())

    # Check for DENY rules before actually deleting/nullifying any other
    # references
    for rule_entry, rule in delete_rules:
        document_cls, field_name = rule_entry
        if document_cls._meta.get("abstract"):
            continue

        if rule == DENY:
            refs = document_cls.objects(**{field_name + "__in": self})
            if refs.limit(1).count() > 0:
                raise OperationError(
                    "Could not delete document (%s.%s refers to it)"
                    % (document_cls.__name__, field_name)
                )

    # Check all the other rules
    for rule_entry, rule in delete_rules:
        document_cls, field_name = rule_entry
        if document_cls._meta.get("abstract"):
            continue

        if rule == CASCADE:
            cascade_refs = set() if cascade_refs is None else cascade_refs
            # Handle recursive reference
            if doc._collection == document_cls._collection:
                for ref in queryset:
                    cascade_refs.add(ref.id)
            refs = document_cls.objects(
                **{field_name + "__in": self, "pk__nin": cascade_refs}
            )
            if refs.count() > 0:
                refs.delete(write_concern=write_concern, cascade_refs=cascade_refs)
        elif rule == NULLIFY:
            document_cls.objects(**{field_name + "__in": self}).update(
                write_concern=write_concern, **{"unset__%s" % field_name: 1}
            )
        elif rule == PULL:
            document_cls.objects(**{field_name + "__in": self}).update(
                write_concern=write_concern, **{"pull_all__%s" % field_name: self}
            )

    with set_write_concern(queryset._collection, write_concern) as collection:
        result = collection.delete_many(queryset._query)

        # If we're using an unack'd write concern, we don't really know how
        # many items have been deleted at this point, hence we only return
        # the count for ack'd ops.
        if result.acknowledged:
            return result.deleted_count

def clone(self):
    """Create a copy of the current queryset."""
    return self._clone_into(self.__class__(self._document, self._collection_obj))

def comment(self, text):
    """Add a comment to the query.

    See https://docs.mongodb.com/manual/reference/method/cursor.comment/#cursor.comment
    for details.
    """
    return self._chainable_method("comment", text)

def max_time_ms(self, ms):
    """Wait `ms` milliseconds before killing the query on the server

    :param ms: the number of milliseconds before killing the query on the server
    """
    return self._chainable_method("max_time_ms", ms)

def _cursor(self):
    """Return a PyMongo cursor object corresponding to this queryset."""

    # If _cursor_obj already exists, return it immediately.
    if self._cursor_obj is not None:
        return self._cursor_obj

    # Create a new PyMongo cursor.
    # XXX In PyMongo 3+, we define the read preference on a collection
    # level, not a cursor level. Thus, we need to get a cloned collection
    # object using `with_options` first.
    if self._read_preference is not None or self._read_concern is not None:
        self._cursor_obj = self._collection.with_options(
            read_preference=self._read_preference, read_concern=self._read_concern
        ).find(self._query, **self._cursor_args)
    else:
        self._cursor_obj = self._collection.find(self._query, **self._cursor_args)

    # Apply "where" clauses to cursor
    if self._where_clause:
        where_clause = self._sub_js_fields(self._where_clause)
        self._cursor_obj.where(where_clause)

    # Apply ordering to the cursor.
    # XXX self._ordering can be equal to:
    # * None if we didn't explicitly call order_by on this queryset.
    # * A list of PyMongo-style sorting tuples.
    # * An empty list if we explicitly called order_by() without any
    #   arguments. This indicates that we want to clear the default
    #   ordering.
    if self._ordering:
        # explicit ordering
        self._cursor_obj.sort(self._ordering)
    elif self._ordering is None and self._document._meta["ordering"]:
        # default ordering
        order = self._get_order_by(self._document._meta["ordering"])
        self._cursor_obj.sort(order)

    if self._limit is not None:
        self._cursor_obj.limit(self._limit)

    if self._skip is not None:
        self._cursor_obj.skip(self._skip)

    if self._hint != -1:
        self._cursor_obj.hint(self._hint)

    if self._collation is not None:
        self._cursor_obj.collation(self._collation)

    if self._batch_size is not None:
        self._cursor_obj.batch_size(self._batch_size)

    if self._comment is not None:
        self._cursor_obj.comment(self._comment)

    return self._cursor_obj

def _cursor_args(self):
    fields_name = "projection"
    # snapshot is not handled at all by PyMongo 3+
    # TODO: evaluate similar possibilities using modifiers
    if self._snapshot:
        msg = "The snapshot option is not anymore available with PyMongo 3+"
        warnings.warn(msg, DeprecationWarning)

    cursor_args = {}
    if not self._timeout:
        cursor_args["no_cursor_timeout"] = True

    if self._allow_disk_use:
        cursor_args["allow_disk_use"] = True

    if self._loaded_fields:
        cursor_args[fields_name] = self._loaded_fields.as_dict()

    if self._search_text:
        if fields_name not in cursor_args:
            cursor_args[fields_name] = {}

        cursor_args[fields_name]["_text_score"] = {"$meta": "textScore"}

    return cursor_args

def as_dict(self):
    field_list = {field: self.value for field in self.fields}
    if self.slice:
        field_list.update(self.slice)
    if self._id is not None:
        field_list["_id"] = self._id
    return field_list

def no_sub_classes(self):
    """Filter for only the instances of this specific document.

    Do NOT return any inherited documents.
    """
    if self._document._meta.get("allow_inheritance") is True:
        self._cls_query = {"_cls": self._document._class_name}

    return self

def __match_all(cls, embedded_doc, kwargs):
    """Return True if a given embedded doc matches all the filter
    kwargs. If it doesn't return False.
    """
    for key, expected_value in kwargs.items():
        doc_val = getattr(embedded_doc, key)
        if doc_val != expected_value and str(doc_val) != expected_value:
            return False
    return True

def __only_matches(cls, embedded_docs, kwargs):
    """Return embedded docs that match the filter kwargs."""
    if not kwargs:
        return embedded_docs
    return [doc for doc in embedded_docs if cls.__match_all(doc, kwargs)]

def first(self):
    """Return the first embedded document in the list, or ``None``
    if empty.
    """
    if len(self) > 0:
        return self[0]

def _sort_key(field_tuple):
    _, value = field_tuple
    if isinstance(value, int):
        return value  # 0 for exclusion, 1 for inclusion
    return 2  # so that complex values appear last

def __add__(self, f):
    if isinstance(f.value, dict):
        for field in f.fields:
            self.slice[field] = f.value
        if not self.fields:
            self.fields = f.fields
    elif not self.fields:
        self.fields = f.fields
        self.value = f.value
        self.slice = {}
    elif self.value is self.ONLY and f.value is self.ONLY:
        self._clean_slice()
        if self._only_called:
            self.fields = self.fields.union(f.fields)
        else:
            self.fields = f.fields
    elif self.value is self.EXCLUDE and f.value is self.EXCLUDE:
        self.fields = self.fields.union(f.fields)
        self._clean_slice()
    elif self.value is self.ONLY and f.value is self.EXCLUDE:
        self.fields -= f.fields
        self._clean_slice()
    elif self.value is self.EXCLUDE and f.value is self.ONLY:
        self.value = self.ONLY
        self.fields = f.fields - self.fields
        self._clean_slice()

    if "_id" in f.fields:
        self._id = f.value

    if self.always_include:
        if self.value is self.ONLY and self.fields:
            if sorted(self.slice.keys()) != sorted(self.fields):
                self.fields = self.fields.union(self.always_include)
        else:
            self.fields -= self.always_include

    if getattr(f, "_only_called", False):
        self._only_called = True
    return self

def _clean_slice(self):
    if self.slice:
        for field in set(self.slice.keys()) - self.fields:
            del self.slice[field]

def values_list(self, *fields):
    """An alias for scalar"""
    return self.scalar(*fields)

def _query(self):
    if self._mongo_query is None:
        self._mongo_query = self._query_obj.to_query(self._document)
        if self._cls_query:
            if "_cls" in self._mongo_query:
                self._mongo_query = {"$and": [self._cls_query, self._mongo_query]}
            else:
                self._mongo_query.update(self._cls_query)
    return self._mongo_query

def _fields_to_dbfields(self, fields):
    """Translate fields' paths to their db equivalents."""
    subclasses = []
    if self._document._meta["allow_inheritance"]:
        subclasses = [get_document(x) for x in self._document._subclasses][1:]

    db_field_paths = []
    for field in fields:
        field_parts = field.split(".")
        try:
            field = ".".join(
                f if isinstance(f, str) else f.db_field
                for f in self._document._lookup_field(field_parts)
            )
            db_field_paths.append(field)
        except LookUpError as err:
            found = False

            # If a field path wasn't found on the main document, go
            # through its subclasses and see if it exists on any of them.
            for subdoc in subclasses:
                try:
                    subfield = ".".join(
                        f if isinstance(f, str) else f.db_field
                        for f in subdoc._lookup_field(field_parts)
                    )
                    db_field_paths.append(subfield)
                    found = True
                    break
                except LookUpError:
                    pass

            if not found:
                raise err

    return db_field_paths

def field_path_sub(match):
    # Extract just the field name, and look up the field objects
    field_name = match.group(1).split(".")
    fields = self._document._lookup_field(field_name)
    # Substitute the correct name for the field into the javascript
    return ".".join([f.db_field for f in fields])

def _translate_field_name(cls, field, sep="."):
    """Translate a field attribute name to a database field name."""
    parts = field.split(sep)
    parts = [f.db_field for f in cls._lookup_field(parts)]
    return ".".join(parts)

def _item_frequencies_map_reduce(self, field, normalize=False):
    map_func = """
        function() {{
            var path = '{{{{~{field}}}}}'.split('.');
            var field = this;

            for (p in path) {{
                if (typeof field != 'undefined')
                   field = field[path[p]];
                else
                   break;
            }}
            if (field && field.constructor == Array) {{
                field.forEach(function(item) {{
                    emit(item, 1);
                }});
            }} else if (typeof field != 'undefined') {{
                emit(field, 1);
            }} else {{
                emit(null, 1);
            }}
        }}
    """.format(
        field=field
    )
    reduce_func = """
        function(key, values) {
            var total = 0;
            var valuesSize = values.length;
            for (var i=0; i < valuesSize; i++) {
                total += parseInt(values[i], 10);
            }
            return total;
        }
    """
    values = self.map_reduce(map_func, reduce_func, "inline")
    frequencies = {}
    for f in values:
        key = f.key
        if isinstance(key, float):
            if int(key) == key:
                key = int(key)
        frequencies[key] = int(f.value)

    if normalize:
        count = sum(frequencies.values())
        frequencies = {k: float(v) / count for k, v in frequencies.items()}

    return frequencies

def _item_frequencies_exec_js(self, field, normalize=False):
    """Uses exec_js to execute"""
    freq_func = """
        function(path) {
            var path = path.split('.');

            var total = 0.0;
            db[collection].find(query).forEach(function(doc) {
                var field = doc;
                for (p in path) {
                    if (field)
                        field = field[path[p]];
                     else
                        break;
                }
                if (field && field.constructor == Array) {
                   total += field.length;
                } else {
                   total++;
                }
            });

            var frequencies = {};
            var types = {};
            var inc = 1.0;

            db[collection].find(query).forEach(function(doc) {
                field = doc;
                for (p in path) {
                    if (field)
                        field = field[path[p]];
                    else
                        break;
                }
                if (field && field.constructor == Array) {
                    field.forEach(function(item) {
                        frequencies[item] = inc + (isNaN(frequencies[item]) ? 0: frequencies[item]);
                    });
                } else {
                    var item = field;
                    types[item] = item;
                    frequencies[item] = inc + (isNaN(frequencies[item]) ? 0: frequencies[item]);
                }
            });
            return [total, frequencies, types];
        }
    """
    total, data, types = self.exec_js(freq_func, field)
    values = {types.get(k): int(v) for k, v in data.items()}

    if normalize:
        values = {k: float(v) / total for k, v in values.items()}

    frequencies = {}
    for k, v in values.items():
        if isinstance(k, float):
            if int(k) == k:
                k = int(k)

        frequencies[k] = v

    return frequencies

def __deepcopy__(self, memo):
    """Essential for chained queries with ReferenceFields involved"""
    return self.clone()

def __get__(self, instance, owner):
    """Descriptor for retrieving a value from a field in a document."""
    if instance is None:
        # Document class being used rather than a document object
        return self

    # Get value from document instance if available
    return instance._data.get(self.name)

def __setattr__(self, name, value):
    # Handle dynamic data only if an initialised dynamic document
    if self._dynamic and not self._dynamic_lock:
        if name not in self._fields_ordered and not name.startswith("_"):
            DynamicField = _import_class("DynamicField")
            field = DynamicField(db_field=name, null=True)
            field.name = name
            self._dynamic_fields[name] = field
            self._fields_ordered += (name,)

        if not name.startswith("_"):
            value = self.__expand_dynamic_values(name, value)

        # Handle marking data as changed
        if name in self._dynamic_fields:
            self._data[name] = value
            if hasattr(self, "_changed_fields"):
                self._mark_as_changed(name)
    try:
        self__created = self._created
    except AttributeError:
        self__created = True

    if (
        self._is_document
        and not self__created
        and name in self._meta.get("shard_key", tuple())
        and self._data.get(name) != value
    ):
        msg = "Shard Keys are immutable. Tried to update %s" % name
        raise OperationError(msg)

    try:
        self__initialised = self._initialised
    except AttributeError:
        self__initialised = False

    # Check if the user has created a new instance of a class
    if (
        self._is_document
        and self__initialised
        and self__created
        and name == self._meta.get("id_field")
    ):
        super().__setattr__("_created", False)

    super().__setattr__(name, value)

def __expand_dynamic_values(self, name, value):
    """Expand any dynamic values to their correct types / values."""
    if not isinstance(value, (dict, list, tuple)):
        return value

    # If the value is a dict with '_cls' in it, turn it into a document
    is_dict = isinstance(value, dict)
    if is_dict and "_cls" in value:
        cls = get_document(value["_cls"])
        return cls(**value)

    if is_dict:
        value = {k: self.__expand_dynamic_values(k, v) for k, v in value.items()}
    else:
        value = [self.__expand_dynamic_values(name, v) for v in value]

    # Convert lists / values so we can watch for any changes on them
    EmbeddedDocumentListField = _import_class("EmbeddedDocumentListField")
    if isinstance(value, (list, tuple)) and not isinstance(value, BaseList):
        if issubclass(type(self), EmbeddedDocumentListField):
            value = EmbeddedDocumentList(value, self, name)
        else:
            value = BaseList(value, self, name)
    elif isinstance(value, dict) and not isinstance(value, BaseDict):
        value = BaseDict(value, self, name)

    return value

def _mark_as_changed(self, key):
    """Mark a key as explicitly changed by the user."""
    if not hasattr(self, "_changed_fields"):
        return

    if "." in key:
        key, rest = key.split(".", 1)
        key = self._db_field_map.get(key, key)
        key = f"{key}.{rest}"
    else:
        key = self._db_field_map.get(key, key)

    if key not in self._changed_fields:
        levels, idx = key.split("."), 1
        while idx <= len(levels):
            if ".".join(levels[:idx]) in self._changed_fields:
                break
            idx += 1
        else:
            self._changed_fields.append(key)
            # remove lower level changed fields
            level = ".".join(levels[:idx]) + "."
            remove = self._changed_fields.remove
            for field in self._changed_fields[:]:
                if field.startswith(level):
                    remove(field)

def __getstate__(self):
    data = {}
    for k in (
        "_changed_fields",
        "_initialised",
        "_created",
        "_dynamic_fields",
        "_fields_ordered",
    ):
        if hasattr(self, k):
            data[k] = getattr(self, k)
    data["_data"] = self.to_mongo()
    return data

def pop(self, key, default=None):
    v = self.get(key, default)
    try:
        delattr(self, key)
    except AttributeError:
        pass
    return v

def __getitem__(self, name):
    """Dictionary-style field access, return a field's value if present."""
    try:
        if name in self._fields_ordered:
            return getattr(self, name)
    except AttributeError:
        pass
    raise KeyError(name)

def __setitem__(self, name, value):
    """Dictionary-style field access, set a field's value."""
    # Ensure that the field exists before settings its value
    if not self._dynamic and name not in self._fields:
        raise KeyError(name)
    return setattr(self, name, value)

def get(self, key, default=None):
    # get does not use __getitem__ by default so we must override it as well
    try:
        return self.__getitem__(key)
    except KeyError:
        return default

def compiled_regex(self):
    if self._compiled_regex is None:
        self._compiled_regex = re.compile(self._pattern, self._flags)
    return self._compiled_regex
